package dk.sdu.cbse.gamelab; public final class PlayerComponent implements IGamePluginService,IEntityProcessingService{public void start(GameData d){Entity p=new Entity("PLAYER",400,300,16);p.health=3;d.entities.add(p);}public void stop(GameData d){d.entities.removeIf(e->e.type.equals("PLAYER"));}public void process(GameData d,double dt){Entity p=d.entities.stream().filter(e->e.type.equals("PLAYER")).findFirst().orElse(null);if(p==null)return;if(d.keys.contains("LEFT"))p.rotation-=180*dt;if(d.keys.contains("RIGHT"))p.rotation+=180*dt;if(d.keys.contains("UP")){double a=Math.toRadians(p.rotation);p.dx+=Math.cos(a)*90*dt;p.dy+=Math.sin(a)*90*dt;}p.x+=p.dx*dt;p.y+=p.dy*dt;p.dx*=.99;p.dy*=.99;d.wrap(p);}}